$ErrorActionPreference='Stop'; $root=Resolve-Path (Join-Path $PSScriptRoot '..'); $dist=Join-Path $root 'apps\dim-sum-atlas\dist\squirrel-windows'; $setup=@(Get-ChildItem $dist -Filter 'Dim-Sum-Atlas-*.exe' -File); if($setup.Count -eq 1){$s=& powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $PSScriptRoot 'get-installer-signature.ps1') -Dist $dist; if($LASTEXITCODE -ne 0 -or $s -ne 'NotSigned'){throw 'Existing setup did not report NotSigned.'}}; $temp=Join-Path $env:TEMP "installer-helper-$PID"; $fixture=Join-Path $temp 'squirrel-windows'; New-Item -ItemType Directory -Force $fixture | Out-Null; $sentinel=Join-Path $temp 'sentinel'; Set-Content $sentinel 'start'; foreach($n in @('Dim-Sum-Atlas-0.1.1-win-x64.exe','RELEASES','dim-sum-atlas-0.1.1-full.nupkg','installer-manifest.json')){Set-Content (Join-Path $fixture $n) old}; $caught=$false; try{& (Join-Path $PSScriptRoot 'assert-installer-fresh.ps1') -Sentinel $sentinel -Dist $fixture | Out-Null}catch{$caught=$true}; if(-not $caught){throw 'Stale fixture was accepted.'}; Start-Sleep -Milliseconds 1100; foreach($n in @('Dim-Sum-Atlas-0.1.1-win-x64.exe','RELEASES','dim-sum-atlas-0.1.1-full.nupkg','installer-manifest.json')){(Get-Item (Join-Path $fixture $n)).LastWriteTimeUtc=(Get-Date).ToUniversalTime()}; & (Join-Path $PSScriptRoot 'assert-installer-fresh.ps1') -Sentinel $sentinel -Dist $fixture | Out-Null; $outside=Join-Path $env:TEMP 'outside-installer'; $caught=$false; try{& (Join-Path $PSScriptRoot 'assert-installer-fresh.ps1') -Sentinel $sentinel -Dist $outside | Out-Null}catch{$caught=$true}; if(-not $caught){throw 'Escaped fixture was accepted.'}; Remove-Item $temp -Recurse -Force -ErrorAction SilentlyContinue; Write-Output 'PASS installer helper regression'
